sys_script.script:
(function executeRule(current, previous) {

    var assignmentId = current.getValue('license_assignment');

    var count30 = 0;
    var count90 = 0;

    // Calculate date 30 days ago
    var date30 = new GlideDateTime();
    date30.addDaysUTC(-30);

    // Calculate date 90 days ago
    var date90 = new GlideDateTime();
    date90.addDaysUTC(-90);


    // Count usage records in last 30 days
    var usage30 = new GlideRecord(
        'x_1904737_smart_0_usage_record'
    );

    usage30.addQuery(
        'license_assignment',
        assignmentId
    );

    usage30.addQuery(
        'usage_date',
        '>=',
        date30
    );

    usage30.query();

    while (usage30.next()) {
        count30++;
    }


    // Count usage records in last 90 days
    var usage90 = new GlideRecord(
        'x_1904737_smart_0_usage_record'
    );

    usage90.addQuery(
        'license_assignment',
        assignmentId
    );

    usage90.addQuery(
        'usage_date',
        '>=',
        date90
    );

    usage90.query();

    while (usage90.next()) {
        count90++;
    }


    // Get License Assignment
    var assignment = new GlideRecord(
        'x_1904737_smart_0_license_assignment'
    );

    if (assignment.get(assignmentId)) {

        // Update usage counts
        assignment.setValue(
            'usage_count_30_days',
            count30
        );

        assignment.setValue(
            'usage_count_90_days',
            count90
        );


        // Calculate Usage Status
        if (count90 == 0) {

            assignment.setValue(
                'usage_status',
                'never_used'
            );

        } else if (count30 == 0) {

            assignment.setValue(
                'usage_status',
                'inactive'
            );

        } else if (count30 < 5) {

            assignment.setValue(
                'usage_status',
                'low_usage'
            );

        } else {

            assignment.setValue(
                'usage_status',
                'active'
            );

        }


        // Update License Assignment
        assignment.update();
    }

})(current, previous);
